*/
scwin.regKeywrd = async function () {
    /* sdd-asis-lifecycle:begin fn_regKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('ipt_newKeywrdNm').getValue().length == 0) {
